def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Find the contiguous row pattern that serves as the object to copy.
    motif = None
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            if c - start >= 2:
                motif = row[start:c]
                break
        if motif is not None:
            break

    out = [row[:] for row in grid]
    if motif is None:
        return out

    motif_colors = set(motif)
    marker_colors = {x for row in grid for x in row if x != bg} - motif_colors
    if not marker_colors:
        return out

    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value in marker_colors:
                start = c - len(motif) // 2
                for i, color in enumerate(motif):
                    j = start + i
                    if 0 <= j < w:
                        out[r][j] = color
    return out
